const q = $input.first().json.query || {};
const id = String(q.e_customer_id || '').trim();
if (!/^\d+$/.test(id)) return [{ json: { ok: false, statusCode: 400, body: { error: 'Missing or invalid e_customer_id' } } }];
return [{ json: { ok: true, id } }];

// Field names billToId and shipToLists[{ shipToId }] come from the Eclipse
// node's customer create/update fields (UNVERIFIED against a live GET).
const id = $('Validate').first().json.id;
const r = $input.first().json;
if (r.error) {
  return [{ json: { ok: false, statusCode: 502, body: { error: 'Eclipse customer lookup failed: ' + r.error + (r.message ? ' ' + JSON.stringify(r.message).substring(0, 300) : '') } } }];
}
const c = (Array.isArray(r.results) ? r.results : []).find((x) => String(x.id) === id);
if (!c) return [{ json: { ok: false, statusCode: 404, body: { error: 'No Eclipse customer with id ' + id } } }];

const val = (v) => (v && typeof v === 'object') ? String(v.id || v.shipToId || v.billToId || '') : (v == null ? '' : String(v));
const isBillTo = c.isBillTo === true;
const isShipTo = c.isShipTo === true;
const billToId = isBillTo ? id : (val(c.billToId) || id);
let shipToIds = [id];
if (isBillTo) {
  shipToIds = (Array.isArray(c.shipToLists) ? c.shipToLists : []).map((s) => val(s.shipToId != null ? s.shipToId : s)).filter((s) => s && s !== id);
  if (isShipTo) shipToIds.unshift(id);
}
shipToIds = [...new Set(shipToIds)];
const allIds = [...new Set([id, billToId, ...shipToIds])];

// Eclipse's id filter goes in the query string; keep each call to 100 ids.
const chunks = [];
for (let i = 0; i < allIds.length; i += 100) chunks.push(allIds.slice(i, i + 100).join(','));
return chunks.map((ids, i) => ({ json: {
  ok: true, ids,
  plan: i === 0 ? { id, billToId, shipToIds, allIds, isBillTo, isShipTo } : undefined,
} }));

// Eclipse field names here are confirmed against live responses
// (2026-10-17). HubSpot only adds the record id and coordinates; it is
// best-effort, so a failure leaves hs_id / latitude / longitude empty.
const plan = $('Resolve').first().json.plan;
const s = (v) => (v == null ? '' : (typeof v === 'object' ? String(v.id || v.code || v.name || '') : String(v)).trim());

const eclipse = {};
let eclipseError = '';
for (const it of $('Eclipse: get customers').all()) {
  const r = it.json;
  if (r.error) { eclipseError = String(r.error); continue; }
  for (const c of (Array.isArray(r.results) ? r.results : [])) eclipse[s(c.id)] = c;
}
if (!eclipse[plan.id]) {
  return [{ json: { statusCode: 502, body: { error: 'Eclipse customer details failed' + (eclipseError ? ': ' + eclipseError : '') } } }];
}

const hs = {};
const hsResp = $input.first().json;
for (const row of (Array.isArray(hsResp.results) ? hsResp.results : [])) {
  const p = row.properties || {};
  if (p.e_customer_id) hs[String(p.e_customer_id)] = row;
}

const party = (id) => {
  const c = eclipse[id] || {};
  const row = hs[id];
  const p = (row && row.properties) || {};
  const lat = parseFloat(p.latitude), lng = parseFloat(p.longitude);
  return {
    e_customer_id: id,
    name: s(c.name) || ('Customer ' + id),
    hs_id: (row && row.id) || '',
    address_line1: s(c.addressLine1),
    address_line2: s(c.addressLine2),
    city: s(c.city),
    state: s(c.state),
    postal_code: s(c.postalCode),
    country: s(c.countryCode),
    is_bill_to: c.isBillTo === true,
    is_ship_to: c.isShipTo === true,
    home_branch: s(c.homeBranch),
    price_class: s(c.defaultPriceClass),
    release_number: s(c.defaultReleaseNumber),
    terms_code: s(c.defaultTerms),
    credit_limit: c.creditLimit && c.creditLimit.value != null && isFinite(Number(c.creditLimit.value))
      ? { value: Number(c.creditLimit.value), currency: s(c.creditLimit.currency) || 'USD' } : null,
    latitude: isFinite(lat) ? lat : null,
    longitude: isFinite(lng) ? lng : null,
    missing: !eclipse[id],
  };
};

const shipTos = plan.shipToIds.map(party);
const needsChoice = plan.isBillTo && (shipTos.length > 1 || (shipTos.length === 1 && shipTos[0].e_customer_id !== plan.id));
return [{ json: { statusCode: 200, body: {
  customer: party(plan.id),
  bill_to: party(plan.billToId),
  ship_tos: shipTos,
  ship_to: needsChoice ? null : (shipTos[0] || null),
  needs_ship_to_choice: needsChoice,
} } }];
